WITH enriched AS (SELECT id, starts_on, discount_pct, LAG(discount_pct, 2) OVER w_grp AS prev_discount_pct, ROW_NUMBER() OVER w_grp AS row_seq, FIRST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY channel, promo_code ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel, ROW_NUMBER() OVER w_running AS row_seq_2 FROM promotions WINDOW w_grp AS (PARTITION BY promo_code ORDER BY ends_on, id), w_running AS (PARTITION BY channel ORDER BY starts_on, id)) SELECT CASE WHEN row_seq >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS row_seq_tier, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(prev_discount_pct), 2) AS avg_prev_discount_pct, COUNT(*) AS row_count, ROUND(AVG(row_seq), 2) AS avg_row_seq, SUM(discount_pct) AS total_discount_pct FROM enriched GROUP BY row_seq_tier ORDER BY row_seq_tier DESC;
